<?php
session_start();$ok=false;$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{$h=trim($_POST['host']??'127.0.0.1');$u=trim($_POST['user']??'root');$p=(string)($_POST['pass']??'');$n=preg_replace('/[^A-Za-z0-9_]/','',$_POST['name']??'kingdoms');$pdo=new PDO("mysql:host=$h;charset=utf8mb4",$u,$p,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$pdo->exec("CREATE DATABASE IF NOT EXISTS $n CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci");$pdo->exec("USE $n");$sql=["CREATE TABLE IF NOT EXISTS op_worlds(id INT PRIMARY KEY,speed DECIMAL(6,2) NOT NULL DEFAULT 1,start_at INT NOT NULL,created_at INT NOT NULL)","CREATE TABLE IF NOT EXISTS op_players(id INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(40) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,tribe TINYINT NOT NULL,kingdom_id INT NOT NULL DEFAULT 0,gold INT NOT NULL DEFAULT 100,silver INT NOT NULL DEFAULT 0,culture_points INT NOT NULL DEFAULT 0,attack_points INT NOT NULL DEFAULT 0,defence_points INT NOT NULL DEFAULT 0,created_at INT NOT NULL)","CREATE TABLE IF NOT EXISTS op_villages(id INT AUTO_INCREMENT PRIMARY KEY,owner_id INT NOT NULL,name VARCHAR(80) NOT NULL,x INT NOT NULL,y INT NOT NULL,population INT NOT NULL DEFAULT 1,wood DECIMAL(14,2) NOT NULL DEFAULT 750,clay DECIMAL(14,2) NOT NULL DEFAULT 750,iron DECIMAL(14,2) NOT NULL DEFAULT 750,crop DECIMAL(14,2) NOT NULL DEFAULT 750,warehouse_cap INT NOT NULL DEFAULT 800,granary_cap INT NOT NULL DEFAULT 800,crop_upkeep INT NOT NULL DEFAULT 0,last_tick INT NOT NULL,created_at INT NOT NULL,INDEX(owner_id),UNIQUE(x,y))","CREATE TABLE IF NOT EXISTS op_fields(id INT AUTO_INCREMENT PRIMARY KEY,village_id INT NOT NULL,slot TINYINT NOT NULL,type TINYINT NOT NULL,level TINYINT NOT NULL DEFAULT 1,UNIQUE(village_id,slot))","CREATE TABLE IF NOT EXISTS op_buildings(id INT AUTO_INCREMENT PRIMARY KEY,village_id INT NOT NULL,slot TINYINT NOT NULL,type SMALLINT NOT NULL DEFAULT 0,level TINYINT NOT NULL DEFAULT 0,UNIQUE(village_id,slot))","CREATE TABLE IF NOT EXISTS op_build_queue(id INT AUTO_INCREMENT PRIMARY KEY,village_id INT NOT NULL,slot TINYINT NOT NULL,building_type SMALLINT NOT NULL,level TINYINT NOT NULL,action_type TINYINT NOT NULL,start_at INT NOT NULL,finish_at INT NOT NULL,INDEX(village_id,finish_at))","CREATE TABLE IF NOT EXISTS op_units(id INT AUTO_INCREMENT PRIMARY KEY,village_id INT NOT NULL,unit_type INT NOT NULL,amount INT NOT NULL DEFAULT 0,UNIQUE KEY vu(village_id,unit_type))","CREATE TABLE IF NOT EXISTS op_market(id INT AUTO_INCREMENT PRIMARY KEY,seller_id INT NOT NULL,village_id INT NOT NULL,give_type TINYINT NOT NULL,give_amount INT NOT NULL,want_type TINYINT NOT NULL,want_amount INT NOT NULL,created_at INT NOT NULL)","CREATE TABLE IF NOT EXISTS op_reports(id INT AUTO_INCREMENT PRIMARY KEY,owner_id INT NOT NULL,title VARCHAR(120) NOT NULL,body TEXT NOT NULL,created_at INT NOT NULL,seen TINYINT NOT NULL DEFAULT 0,INDEX(owner_id))","CREATE TABLE IF NOT EXISTS op_kingdoms(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(60) NOT NULL,tag VARCHAR(12) NOT NULL,king_id INT NOT NULL,treasures INT NOT NULL DEFAULT 0,victory_points INT NOT NULL DEFAULT 0,created_at INT NOT NULL)","CREATE TABLE IF NOT EXISTS op_quests(id INT AUTO_INCREMENT PRIMARY KEY,player_id INT NOT NULL,quest_key VARCHAR(40) NOT NULL,status TINYINT NOT NULL DEFAULT 0,progress INT NOT NULL DEFAULT 0,UNIQUE(player_id,quest_key))","CREATE TABLE IF NOT EXISTS op_hero(player_id INT PRIMARY KEY,village_id INT NOT NULL,level INT NOT NULL DEFAULT 1,xp INT NOT NULL DEFAULT 0,strength INT NOT NULL DEFAULT 10,health INT NOT NULL DEFAULT 100)"];foreach($sql as $s)$pdo->exec($s);$pdo->exec("INSERT IGNORE INTO op_worlds VALUES(1,1,UNIX_TIMESTAMP(),UNIX_TIMESTAMP())");file_put_contents(__DIR__.'/config.php',"<?php\ndefine('DB_HOST',".var_export($h,true).");define('DB_USER',".var_export($u,true).");define('DB_PASS',".var_export($p,true).");define('DB_NAME',".var_export($n,true).");\n");$ok=true;}catch(Throwable $e){$err=$e->getMessage();}}
?><!doctype html><meta charset="utf-8"><title>Kingdoms Installer</title><style>body{background:#182019;color:#eee;font:16px Arial;margin:0}.box{max-width:600px;margin:70px auto;padding:30px;background:#293128;border:1px solid #806d48;border-radius:8px}input{width:100%;box-sizing:border-box;padding:12px;margin:7px 0 14px;background:#111;color:#fff;border:1px solid #68715e}button{padding:12px 22px;background:#b38a45;color:#fff;border:0;border-radius:4px}.err,.ok{padding:12px;margin-bottom:15px}.err{background:#662e2e}.ok{background:#285b32}</style><div class="box"><h1>Kingdoms Installer</h1><?php if($ok):?><div class="ok">Installatie klaar. <a href="index.php" style="color:#fff">Start het spel</a></div><?php else:?><?php if($err):?><div class="err"><?=htmlspecialchars($err)?></div><?php endif;?><form method="post"><label>MySQL host</label><input name="host" value="127.0.0.1"><label>Gebruiker</label><input name="user" value="root"><label>Wachtwoord</label><input name="pass" type="password"><label>Database</label><input name="name" value="kingdoms"><button>Installeren</button></form><?php endif;?></div>